import sys
from collections import defaultdict

def read_ints():
    return list(map(int, sys.stdin.readline().strip().split()))

def main():
    T = int(sys.stdin.readline().strip())
    for _ in range(T):
        N = int(sys.stdin.readline().strip())
        edges = defaultdict(list)
        for _ in range(N - 1):
            u, v = read_ints()
            edges[u].append(v)
            edges[v].append(u)
        A = read_ints()

        # Find the minimum security value
        min_security = min(A)
        print(min_security)

if __name__ == "__main__":
    main()
